"""Reconcile the registered pilot, costs, paired speed changes and fixed gate."""
import pathlib,json,csv,statistics,math
import numpy as np
import soundfile as sf
from scipy.signal import stft
P=pathlib.Path('/workspace/improvement');D=P/'execution_tradeoff'

def read(p):return json.loads(p.read_text())
def stats(xs):return {'mean':float(np.mean(xs)),'p50':float(np.median(xs)),'p95':float(np.percentile(xs,95)),'min':min(xs),'max':max(xs)}
def main():
 generation=read(D/'pilot/generation-result.json');score=read(D/'pilot/source-summary.json');state=read(D/'exit_receipt.json');assert state['status']=='complete' and state['exit_code']==0
 rs=generation['records'];assert len(rs)==48 and all(r['paired_audio_equal'] and r['paired_delta_equal'] and r['frozen_audio_equal'] for r in rs)
 summaries=score['summary'];raw=summaries['raw50'];anchor=summaries['anchor25'];duration=sum(r['audio_seconds'] for r in rs);loops={};per=[]
 for k in ['twice','once']:
  ts=[r['runs'][k]['wall_seconds'] for r in rs];total=sum(ts);gpu=sum(r['runs'][k]['gpu_event_seconds'] for r in rs);loops[k]={'count':48,'audio_seconds':duration,'wall_seconds':total,'gpu_event_seconds':gpu,'latency_seconds':stats(ts),'seconds_per_audio_second':total/duration,'per_recording_seconds_per_audio_second':stats([r['runs'][k]['wall_seconds']/r['audio_seconds'] for r in rs]),'peak_allocated_bytes':max(r['runs'][k]['peak_allocated_bytes'] for r in rs),'peak_reserved_bytes':max(r['runs'][k]['peak_reserved_bytes'] for r in rs),'phase_wall_seconds':{phase:sum(r['runs'][k]['phase_wall_seconds'][phase] for r in rs) for phase in rs[0]['runs'][k]['phase_wall_seconds']},'phase_gpu_event_seconds':{phase:sum(r['runs'][k]['phase_gpu_event_seconds'][phase] for r in rs) for phase in rs[0]['runs'][k]['phase_gpu_event_seconds']},'source_forward_backward_pairs':sum(r['runs'][k]['source_forward_backward_pairs'] for r in rs),'decoder_forwards':sum(r['runs'][k]['decoder_forwards'] for r in rs),'decoder_backwards':sum(r['runs'][k]['decoder_backwards'] for r in rs)}
  for r in rs:per.append({'id':r['id'],'variant':k,'audio_seconds':r['audio_seconds'],'generation_wall_seconds':r['runs'][k]['wall_seconds'],'seconds_per_audio_second':r['runs'][k]['wall_seconds']/r['audio_seconds'],'gpu_event_seconds':r['runs'][k]['gpu_event_seconds'],'peak_allocated_bytes':r['runs'][k]['peak_allocated_bytes'],'generation_plus_anchor_seconds':r['runs'][k]['wall_seconds']+r['postprocessing']['anchor25']['wall_seconds'],'shared_record_overhead_seconds':max(0.,r['wall_seconds_including_both_paths']-sum(r['runs'][j]['wall_seconds'] for j in ['once','twice'])-sum(v['wall_seconds'] for v in r['postprocessing'].values()))})
 speed=1-loops['once']['wall_seconds']/loops['twice']['wall_seconds'];rng=np.random.default_rng(20261026);a=np.array([r['runs']['twice']['wall_seconds'] for r in rs]);b=np.array([r['runs']['once']['wall_seconds'] for r in rs]);ix=rng.integers(0,48,(10000,48));cis=np.percentile(1-b[ix].sum(1)/a[ix].sum(1),[2.5,97.5]).tolist()
 gate={v:{'quality_pass':all(s['quality'][k]>=floor for k,floor in [('dnsmos',3),('nisqa',3.75),('utmos',3.5)]),'wer_above75':s['error_percent']>75} for v,s in summaries.items()}
 for g in gate.values():g['joint_pass']=g['quality_pass'] and g['wer_above75']
 delta={'wer_percentage_points':anchor['error_percent']-raw['error_percent'],'quality':{k:anchor['quality'][k]-raw['quality'][k] for k in raw['quality']}}
 pp=generation['preprocessing'];post=sum(r['postprocessing']['anchor25']['wall_seconds'] for r in rs);load=generation['encoder_load_wall_seconds']+generation['source_decoder_load_wall_seconds'];warm=generation['warmup_wall_seconds'];shared_overhead=sum(max(0.,r['wall_seconds_including_both_paths']-sum(r['runs'][k]['wall_seconds'] for k in ['once','twice'])-sum(v['wall_seconds'] for v in r['postprocessing'].values())) for r in rs);compute_only=pp['wall_seconds']+loops['once']['wall_seconds']+post;steady=compute_only+shared_overhead
 # Allocation time includes idle/loading between device operations; CUDA events are elapsed stream intervals, not energy or kernel-active integration.
 result={'status':'complete','count':48,'audio_seconds':duration,'source_only':True,'target_models_evaluated':[],'human_intelligibility_established':False,'joint_gates':gate,'quality_delta_anchor_vs_raw':delta,'loops':loops,'paired_speed_reduction_fraction':speed,'paired_speed_reduction_bootstrap95_ci':cis,'bootstrap_scope':'48 exposed recordings resampled as pairs, conditional on this GPU/order/session; not independent system repetitions','efficiency_target_pass':speed>=.1 and loops['once']['peak_allocated_bytes']<20*1024**3,'quality_mechanism_signal':delta['quality']['utmos']>=.15 and delta['wer_percentage_points']>=-5,'costs':{'teacher_generation':loops['once']['wall_seconds'],'feature_preprocessing':pp['wall_seconds'],'training_seconds':0,'spectral_repair':post,'model_loading':load,'warmup':warm,'formal_evaluation':score['resources'],'measured_generation_process_gpu_allocation_wall_seconds':generation['wall_seconds'],'measured_full_cycle_wall_seconds':state['elapsed_wall_seconds'],'gpu_job_process_wall_upper_bound_seconds':generation['wall_seconds']+score['resources']['elapsed_wall_seconds'],'measured_experiment_gpu_event_elapsed_seconds':sum(r['runs'][k]['gpu_event_seconds'] for r in rs for k in ['once','twice'])+pp['gpu_event_seconds']+score['resources']['asr_gpu_event_seconds']+score['resources']['quality_gpu_event_seconds'],'candidate_steady_generation_seconds_excluding_loading':steady,'candidate_compute_seconds_excluding_io_loading':compute_only,'shared_record_io_setup_comparison_overhead_seconds':shared_overhead,'candidate_end_to_end_scope':'Conservative forecast charges all measured shared paired-record setup/comparison/output overhead to one candidate; direct single-path deployment end-to-end was not separately benchmarked','timing_limits':'CUDA stream events can include host dispatch gaps; process allocation time includes idle/I/O and setup. No exact kernel-active hours or energy meter. Candidate endpoint omits instrumentation/IO differences at deployment.'},'forecasts':{'basis':'measured 48-point once loop + feature extraction + fixed repair + all shared paired-record IO/setup/comparison overhead conservatively charged once, same duration/text distribution, batch1 float32 TITAN RTX','new48_seconds_plus_measured_load_warmup':steady+load+warm,'new1000_similar_recordings_hours':(steady/48*1000+load+warm)/3600,'teacher1_audio_hour_allocation_hours':steady/duration,'teacher10_audio_hours_allocation_hours':10*steady/duration,'teacher_corpus_evaluation':'not included; quality/ASR evaluation measured separately','future_student_training':'not measured; no trained student in this cycle','student_break_even':'teacher-data hours + measured training hours divided by measured per-input teacher-minus-student hours; student latency/retention currently unknown','scaling_limit':'Clip-length/token distributions can change padded Whisper/decoder work; 10h is a conditional extrapolation, not authorization to launch from this pilot alone.'},'decision':'candidate_pending'}
 qualified=[v for v,g in gate.items() if g['joint_pass']]
 result['decision']='joint_candidate_needs_freeze_and_next_stage_budget' if qualified else 'scientific_stop_no_joint_pass';result['candidate']=max(qualified,key=lambda v:summaries[v]['error_percent']) if qualified else None
 # Reconcile achieved spectrum after the single inverse transform; never pretend target magnitudes are achieved exactly.
 generated=[json.loads(s) for s in (D/'pilot/generated.jsonl').read_text().splitlines()];old={r['id']:r for r in [json.loads(s) for s in (P/'execution_scaled/fvpilot/generated.jsonl').read_text().splitlines()]};signals=[]
 for r in generated:
  ref,_=sf.read(old[r['id']]['audio']['fv_reconstruction']['path'],dtype='float32');_,_,zr=stft(ref,16000,nperseg=512,noverlap=352)
  vals={}
  for v in ['raw50','stft_identity','anchor25']:
   y,_=sf.read(r['audio'][v]['path'],dtype='float32');_,_,z=stft(y,16000,nperseg=512,noverlap=352);vals[v]=z;signals.append({'id':r['id'],'variant':v,'achieved_logmag_error_to_reconstruction':float(np.mean(np.abs(np.log(np.maximum(np.abs(z),1e-7))-np.log(np.maximum(np.abs(zr),1e-7))))),'achieved_relative_magnitude_error_to_reconstruction':float(np.linalg.norm(np.abs(z)-np.abs(zr))/np.linalg.norm(np.abs(zr)))})
  target=np.exp(.75*np.log(np.maximum(np.abs(vals['raw50']),1e-7))+.25*np.log(np.maximum(np.abs(zr),1e-7)));signals[-1]['target_vs_achieved_relative_magnitude_error']=float(np.linalg.norm(np.abs(vals['anchor25'])-target)/np.linalg.norm(target))
 result['signal_diagnostics']={v:{'mean_logmag_error_to_reconstruction':statistics.mean(s['achieved_logmag_error_to_reconstruction'] for s in signals if s['variant']==v),'mean_relative_magnitude_error_to_reconstruction':statistics.mean(s['achieved_relative_magnitude_error_to_reconstruction'] for s in signals if s['variant']==v)} for v in summaries}
 (D/'achieved_spectra.json').write_text(json.dumps(signals,indent=2)+'\n');(D/'results.json').write_text(json.dumps(result,indent=2)+'\n');(D/'selection.json').write_text(json.dumps({'status':result['decision'],'candidate':result['candidate'],'gates':gate,'selection_is_source_only':True,'validation_or_transfer_launched':False},indent=2)+'\n')
 with (D/'latency_per_recording.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(per[0]));w.writeheader();w.writerows(per)
 print(json.dumps({'status':result['status'],'decision':result['decision'],'speed_reduction':speed,'quality_delta':delta,'gates':gate},indent=2))
if __name__=='__main__':main()
